python3 - <<'EOF'
import re,sys
p="journals/2026-08-19-order-500s-null-price.md"
t=open(p).read()
fm=t.split('---\n',2)[1]
try:
    import yaml
except ImportError:
    print("no pyyaml"); sys.exit(0)
d=yaml.safe_load(fm)
ids={e['id'] for e in d['evidence']}
bad=[]
for h in d['hypotheses']:
    for r in h['evidence_for']+h['evidence_against']:
        if r not in ids: bad.append((h['id'],r))
for l in d.get('latent_findings',[]):
    for r in l['evidence']:
        if r not in ids: bad.append(('latent',r))
print("evidence ids:",sorted(ids,key=lambda x:int(x[1:])))
print("dangling refs:",bad)
rc=d['root_cause']['hypothesis']
print("root_cause ->",rc,"state:",[h['state'] for h in d['hypotheses'] if h['id']==rc])
from datetime import datetime
s=datetime.fromisoformat(str(d['investigation']['started']).replace('Z','+00:00'))
c=datetime.fromisoformat(str(d['investigation']['concluded']).replace('Z','+00:00'))
print("wall clock delta:",(c-s).total_seconds(),"declared:",d['usage']['wall_clock_seconds'])
print("keys ok:",sorted(d.keys()))
EOF
